# Basic while
count = 0
while count < 5:
    print(count, end=' ')  # 0 1 2 3 4
    count += 1

# break and continue
for n in range(10):
    if n == 3:
        continue   # skip 3
    if n == 7:
        break      # stop at 7
    print(n, end=' ')  # 0 1 2 4 5 6

# Input validation pattern
while True:
    age = input('Enter age (1-120): ')
    if age.isdigit() and 1 <= int(age) <= 120:
        break
    print('Invalid input, try again.')
